16	type SubKey = "online" | "inventory" | "roles";
17	
18	export function GamePlayersHub({
19	  serverId,
20	  running,
21	  playersMax,
22	  isMc,
23	}: {
24	  serverId: string;
25	  running: boolean;
26	  playersMax: number | null;
27	  isMc: boolean;
28	}) {
29	  const [sub, setSub] = useState<SubKey>("online");
30	  const visible = SUB_TABS.filter((t) => !t.mc || isMc);
31	
32	  return (
33	    <div className="space-y-5">
34	      {/* Sub-tab pills — only render the bar when there are multiple tabs */}
35	      {visible.length > 1 && (
36	        <div className="flex flex-wrap gap-1.5">
37	          {visible.map((t) => {
38	            const active = sub === t.key;
39	            return (
40	              <button
41	                key={t.key}
42	                type="button"
43	                onClick={() => setSub(t.key as SubKey)}
44	                className={`rounded-xl px-3.5 py-1.5 text-sm font-medium transition-colors ${
45	                  active
46	                    ? "bg-white/[0.08] text-white ring-1 ring-inset ring-brand-500/40"
47	                    : "text-slate-400 hover:bg-white/[0.04] hover:text-white"
48	                }`}
49	              >
50	                {t.label}
51	              </button>
52	            );
53	          })}
54	        </div>
55	      )}
56	
57	      {sub === "online" && (
58	        <GamePlayers serverId={serverId} running={running} playersMax={playersMax} />
59	      )}
60	      {sub === "inventory" && isMc && (
61	        <GameInventory serverId={serverId} running={running} />
62	      )}
63	      {sub === "roles" && isMc && (
64	        <GameRoles serverId={serverId} running={running} />
65	      )}
66	    </div>
67	  );
68	}
