57	  const [supported, setSupported] = useState(true);
58	  const [err, setErr] = useState<string | null>(null);
59	  const [msg, setMsg] = useState<string | null>(null);
60	  const [pending, start] = useTransition();
61	
62	  const refresh = useCallback(() => {
63	    start(async () => {
64	      const r = await getGamePlayers(serverId);
65	      if (r.ok) { setPlayers(r.players); setErr(null); }
66	      else { setErr(r.error); if (/not available/i.test(r.error)) setSupported(false); }
67	    });
68	  }, [serverId]);
69	
70	  useEffect(() => { if (running) refresh(); }, [running, refresh]);
71	
72	  function act(kind: "kick" | "ban", id: string) {
73	    if (kind === "ban" && !window.confirm(`Ban ${id}? They will be disconnected and blocked.`)) return;
74	    setMsg(null);
75	    start(async () => {
76	      const r = kind === "kick" ? await kickPlayer(serverId, id) : await banPlayer(serverId, id);
77	      if (!r.ok) setErr(r.error); else { setMsg(`${kind === "kick" ? "Kicked" : "Banned"} ${id}`); refresh(); }
78	    });
79	  }
80	
81	  function doGamemode(name: string, mode: string) {
82	    setMsg(null);
83	    start(async () => {
84	      const r = await setPlayerGameMode(serverId, name, mode);
85	      if (!r.ok) setErr(r.error); else setMsg(`Set ${name} to ${mode}`);
86	    });
87	  }
88	
89	  function doTp(name: string) {
90	    const target = prompt(`Teleport ${name} to which player?`);
91	    if (!target?.trim()) return;
92	    setMsg(null);
93	    start(async () => {
94	      const r = await teleportPlayer(serverId, name, target.trim());
95	      if (!r.ok) setErr(r.error); else setMsg(`Teleported ${name} → ${target.trim()}`);
96	    });
97	  }
