296	export async function getGamePlayers(
297	  serverId: string
298	): Promise<{ ok: true; players: Player[]; raw: string } | { ok: false; error: string }> {
299	  try {
300	    const { user, server } = await ownedServer(serverId);
301	    const spec = requireSpec(server);
302	    if (spec.rcon !== "source" || !spec.listCommand)
303	      return { ok: false, error: `Player list is not available for ${spec.label}.` };
304	    const limited = throttle(user.id, "players", 40);
305	    if (limited) return { ok: false, error: limited };
306	    if (SANDBOX)
307	      return { ok: true, players: [{ name: "steve" }, { name: "alex" }], raw: "There are 2 of a max of 20 players online: steve, alex" };
308	    if (server.status !== "RUNNING")
309	      return { ok: false, error: "The player list is available only while the server is running." };
310	    const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, spec.listCommand!));
311	    if (!res.ok) return { ok: false, error: res.error };
312	    const parsed = parsePlayers(spec.family, res.response);
313	    return { ok: true, players: parsed.players, raw: parsed.raw };
314	  } catch (err) {
315	    return { ok: false, error: safeError(err) };
316	  }
317	}
