319	async function playerAction(serverId: string, playerId: string, kind: "kick" | "ban"): Promise<Result> {
320	  try {
321	    const { user, server } = await ownedServer(serverId);
322	    const spec = requireSpec(server);
323	    const template = kind === "kick" ? spec.kickCommand : spec.banCommand;
324	    if (spec.rcon !== "source" || !template)
325	      return { ok: false, error: `${kind === "kick" ? "Kick" : "Ban"} is not available for ${spec.label}.` };
326	    const valid = validatePlayerId(playerId);
327	    if (!valid.ok) return { ok: false, error: valid.error };
328	    const limited = throttle(user.id, "player-action", 20);
329	    if (limited) return { ok: false, error: limited };
330	    if (SANDBOX) return { ok: true };
331	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };
332	
333	    const command = template.replace("%s", valid.id);
334	    await db.auditLog.create({
335	      data: { userId: user.id, action: `gameserver.${kind}`, detail: `${spec.family}: ${valid.id}` },
336	    });
337	    const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, command));
338	    return res.ok ? { ok: true } : { ok: false, error: res.error };
339	  } catch (err) {
340	    return { ok: false, error: safeError(err) };
341	  }
342	}
